static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    Densenet121DenseBlockCustomTilingData tiling;
    const gert::Shape* x_shape = context->GetInputShape(0);
    const gert::Shape* y_shape = context->GetInputShape(1);

    auto x_ori = x_shape->GetOriginShape();
    auto y_ori = y_shape->GetOriginShape();

    uint32_t n  = static_cast<uint32_t>(x_ori.GetDim(0));
    uint32_t c1 = static_cast<uint32_t>(x_ori.GetDim(1));
    uint32_t h  = static_cast<uint32_t>(x_ori.GetDim(2));
    uint32_t w  = static_cast<uint32_t>(x_ori.GetDim(3));

    uint32_t c2 = static_cast<uint32_t>(y_ori.GetDim(1));

    uint32_t hw = h * w;

    // 简单设置 tileSize，避免超过本地缓存
    uint32_t tileSize = 8192; // 元素数

    // 设置 BlockDim（按 batch 并行）
    uint32_t blockDim = std::min<uint32_t>(8, std::max<uint32_t>(1, n));
    context->SetBlockDim(blockDim);

    tiling.set_n(n);
    tiling.set_c1hw(c1 * hw);
    tiling.set_c2hw(c2 * hw);
    tiling.set_tileSize(tileSize);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(),
                        context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;
    return ge::GRAPH_SUCCESS;
}
}

